// Generated by `bun run embed:opencode-plugin` from scripts/opencode-installer/. Edit those, never this file.

export const OPENCODE_SH_INSTALLER_SETUP_SH_LINES: readonly string[] = [
	"# The OpenCode step of the shell installers (AGEN-141). This file is a template:",
	"# `bun run embed:opencode-plugin` fills the @@AP_OC_*@@ lines from",
	"# src/shared/opencode-plugin.ts and writes the result into setup-hooks.sh and",
	"# setup-relay.sh (between their markers) and into the /setup.sh template.",
	"# The host installer provides ap_opencode_plugin_1_template and",
	"# ap_opencode_plugin_2_template (print the plugin text with its two holes), and",
	"# ap_write_no_follow / ap_write_private_no_follow / ap_validate_hook_base_url.",
	"# It never runs `opencode`.",
	"# In the all-gated layout the force option is remembered in ~/.agentpulse/opencode-force; only the",
	"# no-opencode option clears it (and it removes the plugins too). Outside that layout nothing is remembered.",
	"AP_OC_SDK_MARKER='node_modules/@opencode-ai/plugin/package.json'",
	"AP_OC_SDK_CONFIG_DEP='\"@opencode-ai/plugin\"'",
	"AP_OC_SDK_RULE='sdk_present'",
	"AP_OC_SDK_CHECK='marker_only'",
	"AP_OC_FOREIGN_EXTS='js ts'",
	"AP_OC_FOREIGN_OPENS='yes'",
	"AP_OC_LAYOUT='v1_flat_v2_dir'",
	"AP_OC_REMEMBERS_FORCE=0",
	"AP_OC_HEADER_PREFIX='// agentpulse-opencode-plugin '",
	"AP_OC_ENTRIES='agentpulse-opencode-1.js|agentpulse-opencode-1.js|1|1|file",
	"agentpulse-opencode-2|agentpulse-opencode-2/index.js|2|0|dir'",
	"AP_OC_MSG_SKIP='OpenCode 1.x plugin: not installed. OpenCode 1.x downloads its plugin SDK (@opencode-ai/plugin) into <dir> only when it finds a plugin there, and while it can'\\''t reach the package registry each start then waits about 70 seconds. It hasn'\\''t downloaded the SDK here, so AgentPulse left its 1.x plugin out. To add it, run your setup command with `| bash -s -- --opencode-force` in place of `| bash` while this machine is online: OpenCode 1.x downloads the SDK on its next start, and setup keeps the plugin from then on. If you don'\\''t use OpenCode 1.x, nothing is needed.'",
	"AP_OC_MSG_FORCE='OpenCode 1.x will download its plugin SDK into <dir> on its next start; until it can reach the package registry, each start waits about 70 seconds.'",
	"AP_OC_NOTE_SERVER_FIRST='Upgrade the AgentPulse server first: an older server stores OpenCode events as ordinary Claude Code sessions.'",
	"AP_OC_NOTE_SERVICE_SKIP='AGENTPULSE_SKIP set in your shell is not seen by a running OpenCode 2 background service; use an exclude rule (agentpulse exclude add <dir>), or stop the service so it restarts with your environment (opencode service stop).'",
	"",
	"# ap_oc_gate_open <sdk> <foreign> <force> <remembered>, each 0 or 1: exit 0 when the gated entries are written.",
	"ap_oc_gate_open() {",
	"\t[ \"$3\" = 1 ] && return 0",
	"\t[ \"$AP_OC_REMEMBERS_FORCE\" = 1 ] && [ \"$4\" = 1 ] && return 0",
	"\t[ \"$AP_OC_SDK_RULE\" = sdk_present ] && [ \"$1\" = 1 ] && return 0",
	"\t[ \"$AP_OC_FOREIGN_OPENS\" = yes ] && [ \"$2\" = 1 ] && return 0",
	"\treturn 1",
	"}",
	"",
	"# ap_oc_foreign_plugin_present <plugins dir>: a plain file there that is not a dot file, not ours, and has a listed extension.",
	"ap_oc_foreign_plugin_present() {",
	"\tlocal p=\"$1\" f n e",
	"\t[ -d \"$p\" ] || return 1",
	"\tfor f in \"$p\"/*; do",
	"\t\t[ -f \"$f\" ] || continue",
	"\t\tn=\"${f##*/}\"",
	"\t\tcase \"$n\" in .*|agentpulse-opencode-1.js|agentpulse-opencode-2.js) continue ;; esac",
	"\t\tfor e in $AP_OC_FOREIGN_EXTS; do",
	"\t\t\tcase \"$n\" in ?*.\"$e\") return 0 ;; esac",
	"\t\tdone",
	"\tdone",
	"\treturn 1",
	"}",
	"",
	"# ap_oc_fill <text> <hole> <value>: <text> with every <hole> replaced by <value>, without any pattern or \"&\" meaning.",
	"ap_oc_fill() {",
	"\tlocal t=\"$1\" h=\"$2\" v=\"$3\" out=\"\"",
	"\twhile [[ \"$t\" == *\"$h\"* ]]; do",
	"\t\tout=\"$out${t%%\"$h\"*}$v\"",
	"\t\tt=\"${t#*\"$h\"}\"",
	"\tdone",
	"\tprintf '%s' \"$out$t\"",
	"}",
	"",
	"ap_oc_first_line_is_ours() {",
	"\tlocal first=\"\"",
	"\t[ -f \"$1\" ] || return 1",
	"\tIFS= read -r first < \"$1\" || true",
	"\tcase \"$first\" in \"$AP_OC_HEADER_PREFIX\"*) return 0 ;; esac",
	"\treturn 1",
	"}",
	"",
	"ap_oc_config_dir() {",
	"\tif [ -n \"${OPENCODE_CONFIG_DIR:-}\" ] && [ \"${OPENCODE_CONFIG_DIR#/}\" != \"$OPENCODE_CONFIG_DIR\" ]; then",
	"\t\tprintf '%s' \"${OPENCODE_CONFIG_DIR%/}\"",
	"\telif [ -n \"${XDG_CONFIG_HOME:-}\" ] && [ \"${XDG_CONFIG_HOME#/}\" != \"$XDG_CONFIG_HOME\" ]; then",
	"\t\tprintf '%s' \"${XDG_CONFIG_HOME%/}/opencode\"",
	"\telse",
	"\t\tprintf '%s' \"$HOME/.config/opencode\"",
	"\tfi",
	"}",
	"",
	"ap_oc_data_dir() {",
	"\tif [ -n \"${XDG_DATA_HOME:-}\" ] && [ \"${XDG_DATA_HOME#/}\" != \"$XDG_DATA_HOME\" ]; then",
	"\t\tprintf '%s' \"${XDG_DATA_HOME%/}/opencode\"",
	"\telse",
	"\t\tprintf '%s' \"$HOME/.local/share/opencode\"",
	"\tfi",
	"}",
	"",
	"# ap_oc_detected: OpenCode is here when `opencode` is on PATH or its config or data folder exists. Nothing is run.",
	"ap_oc_detected() {",
	"\tlocal cfg data",
	"\tcfg=\"$(ap_oc_config_dir)\"",
	"\tdata=\"$(ap_oc_data_dir)\"",
	"\tcommand -v opencode >/dev/null 2>&1 || [ -e \"$cfg\" ] || [ -L \"$cfg\" ] || [ -e \"$data\" ]",
	"}",
	"",
	"ap_oc_backup() {",
	"\tlocal path=\"$1\" to",
	"\tto=\"$HOME/.agentpulse/backups/opencode/$(basename -- \"$path\").$(date -u +%Y%m%dT%H%M%SZ)\"",
	"\t( umask 077 && mkdir -p \"$HOME/.agentpulse/backups/opencode\" ) || return 1",
	"\tmv -- \"$path\" \"$to\" || return 1",
	"\techo \"  ✓ Moved $path to $to\"",
	"}",
	"",
	"# ap_oc_remove_ours <plugins dir> <entry> <file> : removes the entry only when line 1 of its file is our header.",
	"ap_oc_remove_ours() {",
	"\tlocal plugins=\"$1\" entry=\"$2\" file=\"$3\" top n extra=0",
	"\ttop=\"$plugins/$entry\"",
	"\tif [ \"$entry\" = \"$file\" ]; then",
	"\t\tif [ -f \"$top\" ] && [ ! -L \"$top\" ] && ap_oc_first_line_is_ours \"$top\"; then",
	"\t\t\trm -f -- \"$top\"",
	"\t\t\techo \"  ✓ Removed OpenCode plugin $top\"",
	"\t\tfi",
	"\t\treturn 0",
	"\tfi",
	"\t[ -d \"$top\" ] && [ ! -L \"$top\" ] || return 0",
	"\tap_oc_first_line_is_ours \"$top/index.js\" || return 0",
	"\tfor n in \"$top\"/* \"$top\"/.[!.]* \"$top\"/..?*; do",
	"\t\t[ -e \"$n\" ] || [ -L \"$n\" ] || continue",
	"\t\t[ \"${n##*/}\" = \"index.js\" ] || extra=1",
	"\tdone",
	"\tif [ \"$extra\" = 0 ]; then",
	"\t\trm -f -- \"$top/index.js\"",
	"\t\trmdir -- \"$top\"",
	"\t\techo \"  ✓ Removed OpenCode plugin $top\"",
	"\telse",
	"\t\tap_oc_backup \"$top\"",
	"\tfi",
	"}",
	"",
	"# ap_oc_write_entry <plugins dir> <entry> <file> <line 1|2> <base> <direct>: writes (or leaves unchanged) one entry.",
	"ap_oc_write_entry() {",
	"\tlocal plugins=\"$1\" entry=\"$2\" file=\"$3\" line=\"$4\" base=\"$5\" direct=\"$6\" text abs top cur",
	"\ttext=\"$(ap_opencode_plugin_${line}_template)\"",
	"\ttext=\"$(ap_oc_fill \"$text\" '@@AP_OPENCODE_BASE_URL@@' \"$base\")\"",
	"\ttext=\"$(ap_oc_fill \"$text\" '@@AP_OPENCODE_DIRECT@@' \"$direct\")\"",
	"\tcase \"$text\" in",
	"\t\t\"$AP_OC_HEADER_PREFIX\"*) ;;",
	"\t\t*) echo \"  ✗ OpenCode: this copy of the installer doesn't carry the plugin text, so nothing was written. Use the installer your AgentPulse server serves.\" >&2; return 1 ;;",
	"\tesac",
	"\t# $(...) took the trailing line break off; the file ends with exactly one, as buildOpenCodePluginFiles' text does.",
	"\ttext=\"$text\"$'\\n'",
	"\tabs=\"$plugins/$file\"",
	"\ttop=\"$plugins/$entry\"",
	"\tif [ \"$entry\" != \"$file\" ] && [ -e \"$top\" ] && [ ! -d \"$top\" ]; then",
	"\t\tap_oc_backup \"$top\" || return 1",
	"\tfi",
	"\tmkdir -p -- \"$(dirname -- \"$abs\")\"",
	"\tif [ -f \"$abs\" ] && [ ! -L \"$abs\" ]; then",
	"\t\tcur=\"$(cat -- \"$abs\"; printf x)\"",
	"\t\tif [ \"$cur\" = \"${text}x\" ]; then",
	"\t\t\techo \"  ✓ OpenCode plugin unchanged: $abs\"",
	"\t\t\treturn 0",
	"\t\tfi",
	"\t\tif ! ap_oc_first_line_is_ours \"$abs\"; then ap_oc_backup \"$abs\" || return 1; fi",
	"\tfi",
	"\tprintf '%s' \"$text\" | ap_write_no_follow \"$abs\" || return 1",
	"\techo \"  ✓ OpenCode plugin → $abs\"",
	"}",
	"",
	"# ap_opencode_install <base url> <direct 0|1> <force 0|1> <no-opencode 0|1>",
	"# Returns 1 only when it refused because something it would touch is a symlink.",
	"ap_opencode_install() {",
	"\tlocal base=\"$1\" direct=\"$2\" force=\"$3\" noop=\"$4\"",
	"\tlocal cfg plugins marker=\"$HOME/.agentpulse/opencode-force\" sdk=0 foreign=0 remembered=0 rule=0 open=0 touched=0 from_env=0",
	"\tlocal e_name e_file e_line e_gated e_kind p",
	"\tcfg=\"$(ap_oc_config_dir)\"",
	"\tplugins=\"$cfg/plugins\"",
	"\tfrom_env=0",
	"\tif [ -n \"${OPENCODE_CONFIG_DIR:-}\" ] && [ \"${OPENCODE_CONFIG_DIR#/}\" != \"$OPENCODE_CONFIG_DIR\" ]; then from_env=1; fi",
	"\tif [ \"$noop\" != 1 ] && ! ap_oc_detected; then",
	"\t\techo \"  - OpenCode not detected (no \\`opencode\\` on PATH, no config or data folder); nothing written.\"",
	"\t\treturn 0",
	"\tfi",
	"\tif [ \"$noop\" != 1 ]; then",
	"\t\tap_validate_hook_base_url \"$base\" || return 1",
	"\t\tcase \"$base\" in *'\"'*|*'\\'*|*'@@'*|*$'\\n'*|*$'\\r'*) echo \"invalid AgentPulse base URL for the OpenCode plugin\" >&2; return 1 ;; esac",
	"\tfi",
	"\t# Links first: nothing below writes or removes anything unless none of these is a link.",
	"\twhile IFS='|' read -r e_name e_file e_line e_gated e_kind; do",
	"\t\tif [ \"$e_kind\" = dir ] && [ -L \"$plugins/$e_name\" ]; then",
	"\t\t\techo \"  ✗ OpenCode: refusing to touch $plugins/$e_name: it is a symlink. Nothing was written or removed.\" >&2",
	"\t\t\treturn 1",
	"\t\tfi",
	"\tdone <<< \"$AP_OC_ENTRIES\"",
	"\tfor p in \"$cfg\" \"$plugins\"; do",
	"\t\tif [ -L \"$p\" ]; then",
	"\t\t\techo \"  ✗ OpenCode: refusing to touch $p: it is a symlink. Nothing was written or removed.\" >&2",
	"\t\t\treturn 1",
	"\t\tfi",
	"\tdone",
	"\tif [ \"$noop\" = 1 ]; then",
	"\t\twhile IFS='|' read -r e_name e_file e_line e_gated e_kind; do",
	"\t\t\t\tap_oc_remove_ours \"$plugins\" \"$e_name\" \"$e_file\"",
	"\t\tdone <<< \"$AP_OC_ENTRIES\"",
	"\t\techo \"  - OpenCode plugins removed (no-opencode).\"",
	"\t\treturn 0",
	"\tfi",
	"\t# What setup looks at, read-only; links are followed on purpose.",
	"\tif [ -f \"$cfg/$AP_OC_SDK_MARKER\" ]; then",
	"\t\tsdk=1",
	"\t\tif [ \"$AP_OC_SDK_CHECK\" != marker_only ]; then",
	"\t\t\tif [ -f \"$cfg/package.json\" ] && grep -qF -- \"$AP_OC_SDK_CONFIG_DEP\" \"$cfg/package.json\" 2>/dev/null; then :; else sdk=0; fi",
	"\t\tfi",
	"\tfi",
	"\tap_oc_foreign_plugin_present \"$plugins\" && foreign=1",
	"\t[ \"$force\" = 1 ] || force=0",
	"\tap_oc_gate_open \"$sdk\" \"$foreign\" 0 0 && rule=1",
	"\tap_oc_gate_open \"$sdk\" \"$foreign\" \"$force\" \"$remembered\" && open=1",
	"\twhile IFS='|' read -r e_name e_file e_line e_gated e_kind; do",
	"\t\t[ -n \"$e_name\" ] || continue",
	"\t\tif [ \"$e_gated\" = 1 ] && [ \"$open\" = 0 ]; then",
	"\t\t\tap_oc_remove_ours \"$plugins\" \"$e_name\" \"$e_file\"",
	"\t\telse",
	"\t\t\tap_oc_write_entry \"$plugins\" \"$e_name\" \"$e_file\" \"$e_line\" \"$base\" \"$direct\" || return 1",
	"\t\t\ttouched=1",
	"\t\tfi",
	"\tdone <<< \"$AP_OC_ENTRIES\"",
	"\tif [ \"$from_env\" = 1 ]; then echo \"  - OPENCODE_CONFIG_DIR is set; installing into $cfg/plugins.\"; fi",
	"\tif [ \"$open\" = 0 ]; then",
	"\t\techo \"  $(ap_oc_fill \"$AP_OC_MSG_SKIP\" '<dir>' \"$cfg\")\"",
	"\telif [ \"$force\" = 1 ] && [ \"$rule\" = 0 ]; then",
	"\t\techo \"  $(ap_oc_fill \"$AP_OC_MSG_FORCE\" '<dir>' \"$cfg\")\"",
	"\tfi",
	"\tif [ \"$touched\" = 1 ]; then",
	"\t\techo \"  $AP_OC_NOTE_SERVER_FIRST\"",
	"\t\techo \"  $AP_OC_NOTE_SERVICE_SKIP\"",
	"\tfi",
	"\treturn 0",
	"}",
];
